use vstd::prelude::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> (res: Vec<u64>)
    requires
        a.len() <= 100,
        b.len() <= 100,
        // Prevent potential overflow in length arithmetic (not needed for 100, but keeps specs robust)
        a.len() + b.len() <= usize::MAX,
    ensures
        res.len() == a.len() + b.len(),
        // First part matches `a`
        forall|i: int|
            0 <= i < a.len() ==> res[i] == a[i],
        // Second part matches `b` shifted by a.len()
        forall|i: int|
            a.len() <= i < res.len() ==> res[i] == b[i - a.len()],
{
    let mut res: Vec<u64> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            res.len() == i,
            forall|j: int| 0 <= j < i ==> res[j] == a[j],
    {
        res.push(a[i]);
        i += 1;
    }

    let mut k: usize = 0;
    while k < b.len()
        invariant
            k <= b.len(),
            res.len() == a.len() + k,
            forall|j: int| 0 <= j < a.len() ==> res[j] == a[j],
            forall|j: int| a.len() <= j < res.len() ==> res[j] == b[j - a.len()],
    {
        res.push(b[k]);
        k += 1;
    }

    res
}

} // verus!